import math
from dataclasses import dataclass


@dataclass(frozen=True)
class RetryPolicy:
    max_attempts: int = 3
    base_delay: float = 1.0
    cap_delay: float = 8.0

    def __post_init__(self):
        if (not isinstance(self.max_attempts, int) or isinstance(self.max_attempts, bool)
                or self.max_attempts <= 0):
            raise ValueError("max_attempts must be positive")
        for value in (self.base_delay, self.cap_delay):
            if (not isinstance(value, (int, float)) or isinstance(value, bool)
                    or not math.isfinite(value) or value <= 0):
                raise ValueError("delays must be finite positive numbers")
        if self.cap_delay < self.base_delay:
            raise ValueError("cap_delay must cover base_delay")

    def delay(self, attempt):
        """attempt is the one-based attempt number that just failed."""
        if not isinstance(attempt, int) or isinstance(attempt, bool) or attempt <= 0:
            raise ValueError("attempt must be positive")
        exponent = attempt - 1
        if exponent >= math.log2(self.cap_delay / self.base_delay):
            return self.cap_delay
        return min(self.cap_delay, self.base_delay * (2.0 ** exponent))

